{"yol":"indirim.js","icerik":"export function indirimUygula(fiyat, yuzde) {
  // Yüzde 0 ile 100 arasında olmalı (100 dahil)
  if (yuzde < 0 || yuzde > 100) {
    throw new RangeError('Yüzde 0 ile 100 arasında olmalıdır');
  }

  // İndirimi uygula
  return fiyat * (100 - yuzde) / 100;
}"}

{"yol":"indirim.test.js","icerik":"import test from 'node:test'
import assert from 'node:assert/strict'
import { indirimUygula } from './indirim.js'

test('normal indirim', () => {
  assert.equal(indirimUygula(200, 25), 150)
})

test('aşırı indirim fiyatı sıfırlar', () => {
  assert.equal(indirimUygula(100, 150), 0)
})

test('yüzde 100 indirim fiyatı sıfırlar', () => {
  assert.equal(indirimUygula(100, 100), 0)
})

test('yüzde 0 indirim fiyatı değişmez', () => {
  assert.equal(indirimUygula(100, 0), 100)
})

test('negatif yüzde RangeError fırlatır', () => {
  assert.throws(() => indirimUygula(100, -10), RangeError)
})

test('yüzde 101 RangeError fırlatır', () => {
  assert.throws(() => indirimUygula(100, 101), RangeError)
})"}

